-- PNJ d'ambiance (section 6.5, V5 ; décisions de l'utilisateur du 30/10/2026 : Hurlevent d'abord, ville animée,
-- voyageurs sur les routes plus tard). ambiance.cpp fait apparaître des silhouettes autour du joueur à Hurlevent.
-- Ce ne sont pas des bots : un PNJ ordinaire, ni ciblable ni attaquable, qui marche, discute par gestes ou se repose.
USE acore_world;

-- 900110 : silhouette d'ambiance. Copie du garde de Hurlevent (68), sans script, amicale envers tous (35),
-- non sélectionnable (0x02000000) et insensible aux joueurs et aux PNJ (0x100, 0x200), civile (2) et sans XP (64).
-- Son apparence et ses armes sont tirées au sort à l'apparition dans les deux tables ci-dessous.
CREATE TEMPORARY TABLE tmp_pnj SELECT * FROM creature_template WHERE entry = 68;
UPDATE tmp_pnj SET
    entry = 900110,
    name = 'Aventurier',
    subname = '',
    faction = 35,
    npcflag = 0,
    unit_flags = 33555200,
    flags_extra = 66,
    gossip_menu_id = 0,
    lootid = 0, pickpocketloot = 0, skinloot = 0, mingold = 0, maxgold = 0,
    AIName = '',
    ScriptName = '';
DROP TEMPORARY TABLE tmp_pnj;
SELECT 900110, Idx, CreatureDisplayID, DisplayScale, Probability, VerifiedBuild FROM creature_template_model WHERE CreatureID = 68;

-- Apparences de joueurs : modèles habillés (CreatureDisplayInfoExtra) d'adultes des races de l'Alliance, tirés des PNJ
-- humanoïdes de Hurlevent, Forgefer, Darnassus et l'Exodar (sans gardes, enfants ni déclencheurs) : 742 modèles.
CREATE TABLE IF NOT EXISTS solazeroth_ambiance_apparences (
    display INT UNSIGNED NOT NULL PRIMARY KEY
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Armes en main : jeux d'armes (main droite, main gauche, distance) des PNJ humanoïdes de ces mêmes villes.
CREATE TABLE IF NOT EXISTS solazeroth_ambiance_armes (
    id         INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
    main_droite INT UNSIGNED NOT NULL,
    main_gauche INT UNSIGNED NOT NULL,
    distance    INT UNSIGNED NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

SELECT DISTINCT e.ItemID1, e.ItemID2, e.ItemID3 FROM creature c
JOIN creature_template t ON t.entry = c.id
JOIN creature_equip_template e ON e.CreatureID = t.entry
WHERE c.map IN (0, 1, 530) AND c.zoneId IN (1519, 1537, 1657, 3557) AND t.type = 7 AND e.ItemID1 > 0
  AND t.name NOT REGEXP 'Orphan|Child|Kid|Trigger|Bunny';
